function phase5Upload(string $entity,string $uuid,string $name,string $source,string $client='admin'): array {
    global $baseUrl,$temporaryDirectory,$adminToken,$phase3Tokens,$phase5Process;
    $curl=curl_init($baseUrl.'/api/files');curl_setopt_array($curl,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_TIMEOUT=>15,CURLOPT_COOKIEFILE=>$temporaryDirectory.'/'.$client.'.cookies',CURLOPT_HTTPHEADER=>['X-CSRF-Token: '.($phase3Tokens[$client] ?? $adminToken)],CURLOPT_POSTFIELDS=>['entity'=>$entity,'record'=>$uuid,'process'=>$phase5Process,'file'=>new CURLFile($source,'application/octet-stream',$name)]]);
    $body=curl_exec($curl);$status=curl_getinfo($curl,CURLINFO_HTTP_CODE);return ['status'=>$status,'json'=>json_decode($body,true),'body'=>$body];
}
function phase5Race(array $requests): array {
    global $environment,$phase5Process;
    $writers=[];
    foreach ($requests as $input) {
        $writer=proc_open([PHP_BINARY,__DIR__.'/operations-writer.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__),$environment);
        fwrite($pipes[0],json_encode([...$input,'process'=>$phase5Process]));fclose($pipes[0]);$writers[]=[$writer,$pipes];
    }
    $results=[];foreach ($writers as [$writer,$pipes]) { $out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);verify(proc_close($writer)===0,'Conexión concurrente sin errores: '.$err);$results[]=json_decode($out,true,512,JSON_THROW_ON_ERROR); }return $results;
}
